function timelineMinimapLowerBound(rowIndices: ReadonlyArray<number>, rowIndex: number): number {
  let low = 0;
  let high = rowIndices.length;
  while (low < high) {
    const middle = Math.floor((low + high) / 2);
    if (rowIndices[middle]! < rowIndex) low = middle + 1;
    else high = middle;
  }
  return low;
}

export function resolveTimelineMinimapVisibleItems(input: {
  readonly visibleStart: number | null | undefined;
  readonly visibleEnd: number | null | undefined;
  readonly rowIndices: ReadonlyArray<number>;
}): { start: number; end: number } {
  if (
    input.visibleStart == null ||
    input.visibleEnd == null ||
    input.visibleEnd < input.visibleStart
  ) {
    return { start: 0, end: 0 };
  }
  return {
    start: timelineMinimapLowerBound(input.rowIndices, input.visibleStart),
    end: timelineMinimapLowerBound(input.rowIndices, input.visibleEnd + 1),
  };
}

/** A turn spans its user message up to the next one, so a long reply keeps its strip lit. */
export function isTimelineMinimapTurnVisible(
  turnStartRowIndex: number,
  nextTurnStartRowIndex: number | undefined,
  visibleStart: number | null | undefined,
  visibleEnd: number | null | undefined,
): boolean {
  return (
    visibleStart != null &&
    visibleEnd != null &&
    turnStartRowIndex <= visibleEnd &&
    (nextTurnStartRowIndex === undefined || nextTurnStartRowIndex > visibleStart)
  );
}

