it("uses a thread's model over a seeded draft and saves an explicit pick", async () => {
  const thread = { ...threadWithHistory("thread-model-pick", 1), runs: [] };
  using _environment = installFakeEnvironment([thread], { acceptCommands: true });
  useComposerDraftStore
    .getState()
    .setModelSelection(
      scopeThreadRef(ENVIRONMENT_ID, thread.id),
      createModelSelection(thread.modelSelection!.instanceId, "gpt-5.5"),
    );
  __setClientSettingsForTests({
    ...DEFAULT_CLIENT_SETTINGS,
    onboardingCompletedAt: "2026-01-01T00:00:00.000Z",
  });
  const router = getRouter(
    createMemoryHistory({ initialEntries: [`/${ENVIRONMENT_ID}/${thread.id}`] }),
  );
  await router.load();
  await using _app = await render(<AppRoot router={router} />, {
    // AppRoot brings its own router.
    router: false,
  });
  await expect.element(page.getByText("Answer 0 for thread-model-pick.")).toBeVisible();

  await page.getByRole("button", { name: "GPT-5.4", exact: true }).click();
  await page.getByRole("option", { name: /GPT-5\.5/ }).click();
  await vi.waitFor(() =>
    expect(
      dispatchedCommands().filter((command) => command.type === "thread.model-selection.set"),
    ).toEqual([
      expect.objectContaining({
        threadId: thread.id,
        modelSelection: expect.objectContaining({ instanceId: "codex", model: "gpt-5.5" }),
      }),
    ]),
  );
});

